use std::{env,fs::File,io::{BufRead,BufReader}};
fn main()->Result<(),String>{
 let p=env::args().nth(1).ok_or("usage: analyze FILE")?;
 let mut it=BufReader::new(File::open(p).map_err(|e|e.to_string())?).lines();
 let mut prev:Option<[f64;8]>=None; let mut rows=0u64; let mut min_dt=f64::INFINITY; let mut min_at=0.; let mut crossings=0u64; let mut cross_at=0.; let mut cross_dt=0.; let mut cross_vals=[0.;8]; let mut gate_changes=0u64; let mut blank_changes=0u64;
 for (ln,l) in it.enumerate(){ let s=l.map_err(|e|e.to_string())?; if s.trim().is_empty(){continue}; let v=s.split_whitespace().map(|x|x.parse::<f64>()).collect::<Result<Vec<_>,_>>().map_err(|_|format!("bad row {}",ln+1))?; let x=match v.len(){9=>[v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8]],16=>[v[1],v[3],v[5],v[7],v[9],v[11],v[13],v[15]],n=>return Err(format!("row {} has {} fields (expected 9 or 16)",ln+1,n))}; if x.iter().any(|q|!q.is_finite()){return Err(format!("nonfinite row {}",ln+1))}; rows+=1; if let Some(o)=prev { let dt=x[0]-o[0]; if !(dt>0.){return Err(format!("non-increasing at row {}",ln+1))}; if dt<min_dt{min_dt=dt;min_at=x[0]}; if (o[1]<2.5)!=(x[1]<2.5){crossings+=1;if cross_at==0.{cross_at=x[0];cross_dt=dt;cross_vals=x}}; if (o[2]-x[2]).abs()>1e-9{gate_changes+=1}; if (o[3]-x[3]).abs()>1e-9{blank_changes+=1} } prev=Some(x); }
 if rows<2{return Err("too few rows".into())}; println!("rows={} min_dt={:.17e} min_dt_at={:.17e} hold_2p5_crossings={} first_cross_at={:.17e} first_cross_dt={:.17e} first_cross_values=hold:{:.9e},pwm:{:.9e},blank:{:.9e},pwm_input:{:.9e},drv_req:{:.9e},drv:{:.9e},gate:{:.9e} gate_changes={} blank_changes={}",rows,min_dt,min_at,crossings,cross_at,cross_dt,cross_vals[1],cross_vals[2],cross_vals[3],cross_vals[4],cross_vals[5],cross_vals[6],cross_vals[7],gate_changes,blank_changes); Ok(())
}
